    'goal.start': 'Start', 'goal.notify': 'Notify me',
    'goals.more': 'Don’t see yours? Tell us which habit you want to break',
    'stats.title': 'Real people, real fresh starts.',
    'stats.n1': '150k', 'stats.l1': 'people have already started a plan with Alento',
    'stats.n2': '9 in 10', 'stats.l2': 'say they feel more in control of their habit',
